        }
      }
    },
    gaps_found: { type: 'array', items: { type: 'string' }, description: 'locations you found that were NOT in the provided draft list' },
    notes: { type: 'string' }
  }
}

const CONTEXT = `You are hardening an EXHAUSTIVE affected-location checklist for a large, already-decided refactor of the Codex Dock contract. Do NOT edit files. Cite exact path + symbol/line.

